                }
            } catch (e: Exception) {
                if (cachedData == null || cachedData.isEmpty()) {
                    errorMessage = e.message ?: "未知错误"
                }
            }
            isLoading = false
        }
    }

    // Perform search when search query changes
    LaunchedEffect(searchQuery, isSearchActive) {
        if (isSearchActive) {
            // Add debounce for better UX
